def cyr(s):
 o='';i=0
 while i<len(s):
  k=s[i:i+2].lower() if s[i:i+2].lower() in ('lj','nj','dž') else s[i].lower()
  val=M.get(k,s[i:i+len(k)])
  if s[i].isupper():val=val.upper()
  o+=val;i+=len(k)
 return o
